// This is not autogenerated.
package environment

// IsAdministrative reports whether the environment is an administrative
// environment - one the platform provisions to hold organization-level
// configuration, rather than an ordinary environment someone created to group
// Connections and their Credentials.
//
// The predicate is deliberately positive. EnvironmentPurpose is a bare string
// type, so its zero value is "" - the state every row written before the
// column existed is in, and the state any consumer that has not yet migrated
// its storage will read back. A negative test (`Purpose != EnvironmentPurposeUser`)
// answers "administrative" for that empty value and for any purpose value a
// future schema adds, which is the direction that grants authority by
// accident. Testing for the administrative value explicitly means "", "user",
// and anything unrecognised all answer false and fail closed.
//
// Call this rather than comparing Purpose inline, so there is one place the
// fail-closed reading is enforced.
func (e Environment) IsAdministrative() bool {
	return e.Purpose == EnvironmentPurposeAdministrative
}

// EffectivePurpose returns the environment's purpose with the absent value
// resolved to its documented meaning. Purpose is optional on the wire and
// omitted when empty, and rows predating the column read back as "";
// both mean an ordinary user environment.
//
// Use this when a purpose value has to be displayed, logged, or persisted.
// Use IsAdministrative for authorisation and resolution decisions - it stays
// correct if the enum later grows a value this function has never seen.
func (e Environment) EffectivePurpose() EnvironmentPurpose {
	if e.Purpose == "" {
		return EnvironmentPurposeUser
	}
	return e.Purpose
}
